27	const PROCESSING_FEE = 5;
28	// No test yet drives unknown item types; the spec ultimately requires an error.
29	const UNKNOWN_ITEM_BASE_PREMIUM = 0;
30	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
31	
32	const percentOf = (amount: number, percent: number): number =>
33	  (amount * percent) / 100;
34	
35	const BASE_PREMIUMS = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	} as const satisfies Record<string, number>;
40	
41	type InsurableItemType = keyof typeof BASE_PREMIUMS;
42	
43	const isInsurable = (type: string): type is InsurableItemType =>
44	  type in BASE_PREMIUMS;
45	
46	const basePremiumOf = (item: Item): number =>
47	  isInsurable(item.type) ? BASE_PREMIUMS[item.type] : UNKNOWN_ITEM_BASE_PREMIUM;
48	
49	const policyBasePremiumOf = (items: Item[]): number =>
50	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
51	
52	const quote = (step: QuoteStep): QuoteResult => {
53	  const basePremium = policyBasePremiumOf(step.items);
54	  const firstInsuranceSurcharge = percentOf(
55	    basePremium,
56	    FIRST_INSURANCE_SURCHARGE_PERCENT,
57	  );
58	
59	  return {
60	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
61	  };
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResult => {
65	  return { results: scenario.steps.map(quote) };
66	};
